function Get-SitecSerialSet { param($Hardware,$Physical);$rows=New-Object System.Collections.Generic.List[object];if($Hardware.Motherboard.SerialNumber){$rows.Add([pscustomobject]@{Type='Motherboard';Serial=[string]$Hardware.Motherboard.SerialNumber})};foreach($m in @($Hardware.Memory)){if($m.SerialNumber){$rows.Add([pscustomobject]@{Type='RAM';Serial=[string]$m.SerialNumber})}};foreach($d in @($Hardware.Storage)){if($d.SerialNumber){$rows.Add([pscustomobject]@{Type='Storage';Serial=[string]$d.SerialNumber})}};if($Physical.CpuAtpo){$rows.Add([pscustomobject]@{Type='CPU-ATPO';Serial=[string]$Physical.CpuAtpo})};if($Physical.PsuSerial){$rows.Add([pscustomobject]@{Type='PSU';Serial=[string]$Physical.PsuSerial})};if($Physical.Seal1){$rows.Add([pscustomobject]@{Type='Seal';Serial=[string]$Physical.Seal1})};if($Physical.Seal2){$rows.Add([pscustomobject]@{Type='Seal';Serial=[string]$Physical.Seal2})};@($rows|ForEach-Object{$_.Serial=$_.Serial.Trim().ToUpperInvariant();$_}|Where-Object{$_.Serial}) }
function Find-SitecDuplicateSerials { param([Parameter(Mandatory)][string]$DataRoot,[Parameter(Mandatory)][string]$AssetId,[Parameter(Mandatory)]$Hardware,[Parameter(Mandatory)]$Physical);$index=Join-Path $DataRoot 'fleet-serial-index.csv';if(-not(Test-Path $index)){return @()};$existing=@(Import-Csv $index -ErrorAction SilentlyContinue);$dups=New-Object System.Collections.Generic.List[object];foreach($s in @(Get-SitecSerialSet $Hardware $Physical)){foreach($hit in @($existing|Where-Object{$_.Type -eq $s.Type -and $_.Serial -eq $s.Serial -and $_.AssetId -ne $AssetId})){$dups.Add([pscustomobject]@{Type=$s.Type;Serial=$s.Serial;ExistingAssetId=$hit.AssetId;ExistingRunId=$hit.RunId})}};@($dups) }
function Update-SitecFleetIndex {
 [CmdletBinding()]param([Parameter(Mandatory)][string]$DataRoot,[Parameter(Mandatory)]$Run);New-Item -ItemType Directory -Path $DataRoot -Force|Out-Null;$serialIndex=Join-Path $DataRoot 'fleet-serial-index.csv';$runIndex=Join-Path $DataRoot 'fleet-runs.csv';$lockPath=Join-Path $DataRoot '.fleet-index.lock';$lock=$null
 for($i=0;$i -lt 30;$i++){try{$lock=[IO.File]::Open($lockPath,[IO.FileMode]::OpenOrCreate,[IO.FileAccess]::ReadWrite,[IO.FileShare]::None);break}catch{Start-Sleep -Milliseconds 250}};if(-not $lock){throw 'Could not acquire fleet index lock.'}
 try{$existing=@();if(Test-Path $serialIndex){$existing=@(Import-Csv $serialIndex)};$existing=@($existing|Where-Object{$_.AssetId -ne $Run.AssetId});$new=@(Get-SitecSerialSet $Run.Hardware $Run.Physical|ForEach-Object{[pscustomobject]@{AssetId=$Run.AssetId;RunId=$Run.RunId;Type=$_.Type;Serial=$_.Serial;Timestamp=$Run.CompletedAt}});@($existing+$new)|Export-Csv $serialIndex -NoTypeInformation -Encoding UTF8;$runs=@();if(Test-Path $runIndex){$runs=@(Import-Csv $runIndex)};$runs=@($runs|Where-Object{$_.AssetId -ne $Run.AssetId});$runs += [pscustomobject]@{AssetId=$Run.AssetId;RunId=$Run.RunId;Timestamp=$Run.CompletedAt;ProfileId=$Run.Profile.ProfileId;OverallStatus=$Run.OverallStatus;MotherboardSerial=$Run.Hardware.Motherboard.SerialNumber;StorageSerials=(@($Run.Hardware.Storage|Select-Object -ExpandProperty SerialNumber)-join '|');RamSerials=(@($Run.Hardware.Memory|Select-Object -ExpandProperty SerialNumber)-join '|');CpuAtpo=$Run.Physical.CpuAtpo;PsuSerial=$Run.Physical.PsuSerial;ManifestSha256=$Run.Security.Sha256};$runs|Export-Csv $runIndex -NoTypeInformation -Encoding UTF8}finally{$lock.Dispose()}
}
